 private TextView tv(String s,float z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setPadding(dp(14),dp(10),dp(14),dp(10));t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 private EditText field(String s){EditText e=new EditText(this);e.setHint(s);e.setHintTextColor(Color.LTGRAY);e.setTextColor(Color.WHITE);e.setTextSize(18);e.setSingleLine(true);e.setPadding(dp(16),0,dp(16),0);e.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);GradientDrawable d=new GradientDrawable();d.setColor(Color.rgb(25,25,25));d.setCornerRadius(dp(14));d.setStroke(dp(2),Color.rgb(90,90,90));e.setBackground(d);e.setMinHeight(dp(64));return e;}
 private Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(20);b.setAllCaps(false);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setGravity(Gravity.CENTER);b.setPadding(dp(12),0,dp(12),0);b.setMinimumHeight(dp(76));b.setMinWidth(0);b.setMinimumWidth(0);b.setStateListAnimator(null);b.setVisibility(View.VISIBLE);b.setEnabled(true);b.setClickable(true);b.setFocusable(true);b.setIncludeFontPadding(true);StateListDrawable states=new StateListDrawable();GradientDrawable normal=new GradientDrawable();normal.setColor(Color.rgb(28,28,32));normal.setCornerRadius(dp(16));normal.setStroke(dp(3),gold());GradientDrawable pressed=new GradientDrawable();pressed.setColor(Color.rgb(55,45,24));pressed.setCornerRadius(dp(16));pressed.setStroke(dp(3),gold());GradientDrawable disabled=new GradientDrawable();disabled.setColor(Color.rgb(55,55,58));disabled.setCornerRadius(dp(16));disabled.setStroke(dp(2),Color.DKGRAY);states.addState(new int[]{android.R.attr.state_pressed},pressed);states.addState(new int[]{-android.R.attr.state_enabled},disabled);states.addState(new int[]{},normal);b.setBackground(states);b.setElevation(dp(7));b.setTranslationZ(dp(1));b.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN)v.animate().scaleX(.97f).scaleY(.94f).translationZ(0).setDuration(70).start();else if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL)v.animate().scaleX(1f).scaleY(1f).translationZ(dp(1)).setDuration(100).start();return false;});return b;}
