 private void base(String title){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(16),dp(14),dp(16),dp(16));root.setBackgroundColor(Color.BLACK);TextView top=tv(title,22,gold());top.setGravity(Gravity.CENTER);top.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(top,lp(-1,64,8));ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private void showProgress(String message){h.post(()->{dismissProgress();progress=new ProgressDialog(this);progress.setIndeterminate(true);progress.setCancelable(false);progress.setMessage(message);progress.show();});}
 private void dismissProgress(){h.post(()->{if(progress!=null&&progress.isShowing())progress.dismiss();progress=null;});}
 private void login(){base("مدير ومؤسس وثاق حاتم حسين الحاج رمضان");TextView x=tv("هوية رقمية آمنة",25,Color.WHITE);x.setGravity(Gravity.CENTER);content.addView(x,lp(-1,-2,18));EditText n=field("الاسم الثلاثي"),y=field("سنة الميلاد"),code=field("الرمز الشخصي (6-12 أرقام)");y.setInputType(InputType.TYPE_CLASS_NUMBER);code.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);content.addView(n,lp(-1,64,10));content.addView(y,lp(-1,64,10));content.addView(code,lp(-1,64,14));Button l=btn("تسجيل الدخول"),c=btn("إنشاء هوية جديدة");content.addView(l,lp(-1,76,10));content.addView(c,lp(-1,76,14));l.bringToFront();c.bringToFront();l.setEnabled(true);c.setEnabled(true);content.addView(tv("المؤسس: حاتم حسين الحاج رمضان",14,gold()));l.setOnClickListener(v->{click();auth(n.getText().toString().trim(),y.getText().toString().trim(),code.getText().toString().trim(),false);});c.setOnClickListener(v->{click();auth(n.getText().toString().trim(),y.getText().toString().trim(),code.getText().toString().trim(),true);});}
 private void auth(String n,String y,String code,boolean create){final String name=n.trim(),year=y.trim();if(name.split("\\s+").length<3||!year.matches("\\d{4}")||!code.matches("\\d{6,12}")){toast("أدخل الاسم الثلاثي وسنة الميلاد والرمز الشخصي (6-12 أرقام)");return;}io.execute(()->{try{JSONObject q=new JSONObject();q.put("name",name);q.put("birthYear",Integer.parseInt(year));q.put("personalCode",code);q.put("deviceKey",deviceKey());HttpResult r=request("POST",create?"/api/identity":"/api/login",q.toString(),null);if(r.code>=200&&r.code<300){JSONObject o=new JSONObject(r.body),u=o.getJSONObject("user");prefs.edit().putString(T,o.getString("token")).putString(ID,u.optString("wethaq_id")).putString("db_user_id",u.optString("id")).putString(NAME,u.optString("name",name)).putString(YEAR,year).apply();h.post(this::home);}else{final HttpResult result=r;h.post(()->toast(error(result)));}}catch(Exception e){h.post(()->toast("تعذر الاتصال بالخادم"));}});}
 private void startMessageService(){try{Intent i=new Intent(this,WethaqMessageService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception ignored){}}
 private void home(){stopPolling();base("المؤسس: حاتم حسين الحاج رمضان");TextView me=tv(prefs.getString(NAME,"")+"\n"+prefs.getString(ID,""),18,Color.WHITE);me.setGravity(Gravity.CENTER);content.addView(me,lp(-1,-2,12));menu("⌕  البحث",this::searchScreen);menu("◉  جهات الاتصال",this::contactsScreen);menu("⚙  الإعدادات",this::settingsScreen);menu("♙  المعلومات الشخصية",this::profileScreen);menu("⚠  الشكاوى والتواصل مع المؤسس",this::sendComplaint);menu("👥  الإدارة",()->startActivity(new Intent(this,PublicAdministrationActivity.class)));if(isOwner())menu("🛡  لوحة تحكم المؤسس",this::adminScreen);Button out=btn("تسجيل الخروج");content.addView(out,lp(-1,76,8));out.setOnClickListener(v->{click();stopService(new Intent(this,WethaqMessageService.class));prefs.edit().clear().apply();login();});if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestNotifications();startMessageService();startPolling();}
 private void menu(String s,Runnable r){Button b=btn(s);content.addView(b,lp(-1,76,8));b.setOnClickListener(v->{click();r.run();});}
 private void searchScreen(){base("البحث عن مستخدم");EditText q=field("الاسم أو معرف وَثاق");Button go=btn("بحث"),back=btn("رجوع");LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(q,lp(-1,64,8));content.addView(go,lp(-1,76,8));content.addView(list);content.addView(back,lp(-1,76,8));go.setOnClickListener(v->{click();search(q.getText().toString().trim(),list);});back.setOnClickListener(v->{click();home();});}
 private void search(String q,LinearLayout list){if(q.length()<2){toast("أدخل حرفين على الأقل");return;}io.execute(()->{try{HttpResult r=request("GET","/api/search?q="+URLEncoder.encode(q,"UTF-8"),null,null);if(r.code==200){JSONArray a=new JSONObject(r.body).optJSONArray("users");h.post(()->{list.removeAllViews();if(a==null||a.length()==0){list.addView(tv("لا توجد نتائج",16,Color.GRAY));return;}for(int i=0;i<a.length();i++){JSONObject u=a.optJSONObject(i);String id=u.optString("wethaq_id"),n=u.optString("name");LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL|Gravity.RIGHT);ImageView avatar=new ImageView(this);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setImageDrawable(defaultAvatar());row.addView(avatar,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout text=new LinearLayout(this);text.setOrientation(LinearLayout.VERTICAL);TextView nm=tv(n,18,Color.WHITE),wi=tv(id,13,Color.LTGRAY);text.addView(nm);text.addView(wi);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));Button save=btn("حفظ");row.addView(save,new LinearLayout.LayoutParams(dp(92),dp(68)));list.addView(row,lp(-1,-2,10));loadAvatarInto(id,avatar);save.setOnClickListener(v->{click();saveContact(id,n);});row.setOnClickListener(v->{click();saveContact(id,n);conversation(id,n);});}});}else{final HttpResult result=r;h.post(()->toast(error(result)));}}catch(Exception e){h.post(()->toast("فشل البحث"));}});}
 private Drawable defaultAvatar(){GradientDrawable d=new GradientDrawable();d.setShape(GradientDrawable.OVAL);d.setColor(Color.rgb(48,48,54));d.setStroke(dp(2),gold());d.setSize(dp(50),dp(50));return d;}
 private void saveContact(String id,String n){try{JSONArray a=contacts();for(int i=0;i<a.length();i++)if(id.equals(a.optJSONObject(i).optString("wethaq_id"))){toast("محفوظ مسبقًا");return;}JSONObject o=new JSONObject();o.put("wethaq_id",id);o.put("name",n);a.put(o);prefs.edit().putString(CONTACTS,a.toString()).apply();toast("تم الحفظ ✓");}catch(Exception e){toast("فشل الحفظ");}}
 private void contactsScreen(){base("جهات الاتصال");Button back=btn("رجوع");content.addView(back,lp(-1,76,8));back.setOnClickListener(v->{click();home();});JSONArray a=contacts();if(a.length()==0){content.addView(tv("لا توجد جهات اتصال محفوظة",16,Color.GRAY));return;}for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);String id=o.optString("wethaq_id"),n=o.optString("name");LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL|Gravity.RIGHT);ImageView avatar=new ImageView(this);avatar.setImageDrawable(defaultAvatar());row.addView(avatar,new LinearLayout.LayoutParams(dp(54),dp(54)));TextView name=tv(n,18,Color.WHITE);row.addView(name,new LinearLayout.LayoutParams(0,dp(76),1));content.addView(row,lp(-1,-2,8));loadAvatarInto(id,avatar);row.setOnClickListener(v->{click();conversation(id,n);});}}
 private void conversation(String id,String n){stopPolling();activeId=id;activeName=n;base(n);Button call=btn("📹 مكالمة فيديو"),audioCall=btn("📞 مكالمة صوتية");content.addView(call,lp(-1,76,6));content.addView(audioCall,lp(-1,76,6));audioCall.setOnClickListener(v->{click();startAudioCall();});call.setOnClickListener(v->{click();startVideoCall();});messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.addView(messages);content.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(this);Button mic=btn("🎙"),gallery=btn("▧"),send=btn("إرسال");input=field("اكتب رسالة…");bar.addView(mic,new LinearLayout.LayoutParams(dp(64),dp(76)));bar.addView(gallery,new LinearLayout.LayoutParams(dp(64),dp(76)));bar.addView(input,new LinearLayout.LayoutParams(0,dp(76),1));bar.addView(send,new LinearLayout.LayoutParams(dp(88),dp(76)));root.addView(bar);Button back=btn("‹ جهات الاتصال");root.addView(back,new LinearLayout.LayoutParams(-1,dp(76)));back.setOnClickListener(v->{click();contactsScreen();});send.setOnClickListener(v->{click();send();});mic.setOnClickListener(v->{click();if(recording)stopRecording(true);else startRecording();});gallery.setOnClickListener(v->{click();pickImage();});loadMessages();startPolling();}
 private void loadMessages(){final String target=activeId;if(target==null)return;io.execute(()->{try{HttpResult r=request("GET","/api/messages/"+URLEncoder.encode(target,"UTF-8"),null,auth());if(r.code==200){JSONArray a=new JSONObject(r.body).optJSONArray("messages");h.post(()->{if(target.equals(activeId))render(a);});}}catch(Exception ignored){}});}
 private void render(JSONArray a){if(messages==null)return;messages.removeAllViews();String meW=prefs.getString(ID,"");String meDb=prefs.getString("db_user_id","");if(a==null||a.length()==0){messages.addView(tv("ابدأ المحادثة الآن",17,Color.GRAY));return;}for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;String s=m.optString("sender_id"),senderW=m.optString("sender_wethaq_id"),senderName=m.optString("sender_name","مستخدم");String type=m.optString("message_type","text");boolean mine=meW.equals(senderW)||meDb.equals(s);LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);line.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);ImageView av=new ImageView(this);av.setScaleType(ImageView.ScaleType.CENTER_CROP);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(44),dp(44));ap.setMargins(dp(4),dp(4),dp(4),dp(4));av.setLayoutParams(ap);if(!senderW.isEmpty())loadAvatarInto(senderW,av);line.addView(av);LinearLayout bubble=new LinearLayout(this);bubble.setOrientation(LinearLayout.VERTICAL);bubble.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);TextView name=tv(mine?"أنت":senderName,17,mine?gold():Color.WHITE);name.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);bubble.addView(name);if("image".equals(type)){ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setAdjustViewBounds(true);try{byte[] d=android.util.Base64.decode(m.optString("body"),android.util.Base64.DEFAULT);im.setImageBitmap(BitmapFactory.decodeByteArray(d,0,d.length));}catch(Exception ignored){}bubble.addView(im,new LinearLayout.LayoutParams(dp(260),dp(200)));}else if("audio".equals(type)){Button play=btn("▶ تشغيل صوت");play.setOnClickListener(v->{try{byte[]d=android.util.Base64.decode(m.optString("body"),android.util.Base64.DEFAULT);MediaPlayer mp=new MediaPlayer();mp.setDataSource(new ByteArrayInputStream(d).getPath());}catch(Exception ignored){toast("تعذر تشغيل الصوت");}});bubble.addView(play);}else{bubble.addView(tv(m.optString("body"),16,Color.WHITE));}line.addView(bubble);messages.addView(line,lp(-1,-2,6));}}
